import{_ as r,o as t,c as e,a6 as o}from"./chunks/framework.CGCCzANv.js";const u=JSON.parse('{"title":"MOTHER3（地球冒险3）正统完整剧情","description":"","frontmatter":{"readingTime":"9 min read"},"headers":[],"relativePath":"游戏引擎/游戏设计/系列游戏/MOTHER/MOTHER3.md","filePath":"游戏引擎/游戏设计/系列游戏/MOTHER/MOTHER3.md"}'),n={name:"游戏引擎/游戏设计/系列游戏/MOTHER/MOTHER3.md"};function i(l,a,s,h,d,c){return t(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="mother3-地球冒险3-正统完整剧情" tabindex="-1">MOTHER3（地球冒险3）正统完整剧情 <a class="header-anchor" href="#mother3-地球冒险3-正统完整剧情" aria-label="Permalink to &quot;MOTHER3（地球冒险3）正统完整剧情&quot;">​</a></h1><h2 id="世界观基础-原作设定" tabindex="-1">世界观基础（原作设定） <a class="header-anchor" href="#世界观基础-原作设定" aria-label="Permalink to &quot;世界观基础（原作设定）&quot;">​</a></h2><p>故事发生在<strong>无处群岛（Nowhere Islands）</strong>，时间在MOTHER2多年之后。这座岛屿是旧世界毁灭后幸存者建立的避难地，岛上沉睡一头大地巨龙，<strong>七根魔法针</strong>封印着巨龙。传说：谁拔出最后一根针，巨龙便会苏醒，按照拔针者的内心意志重塑整个世界。 猪面军团（Pigmask Army）在波奇·明奇（Porky Minch，MOTHER2的反派波奇）带领下入侵群岛，改造生物为合成异兽、强行现代化原始村落，想要夺取七根针、操控巨龙。 主角团：卢卡斯（Lucas，PSI）、邦尼（Boney，家犬）、达斯特（Duster，盗贼）、库玛托拉（Kumatora，魔女，强力PSI）。</p><h2 id="第一章-悲剧降临-塔兹米利村起火" tabindex="-1">第一章 悲剧降临，塔兹米利村起火 <a class="header-anchor" href="#第一章-悲剧降临-塔兹米利村起火" aria-label="Permalink to &quot;第一章 悲剧降临，塔兹米利村起火&quot;">​</a></h2><p>宁静的塔兹米利村，卢卡斯、双胞胎哥哥克劳斯、母亲日奈瓦，前去探望外公。猪面军团空袭森林引发大火。父亲弗林特急忙外出寻找家人。 弗林特找到卢卡斯与克劳斯，却发现母亲日奈瓦为保护孩子，被改造后的恐龙德拉戈杀害。悲痛的弗林特失控伤人，被村民关押。哥哥克劳斯一心复仇，偷偷逃出村子，去找那只恐龙。弗林特越狱追击，击杀改造德拉戈，却找不到克劳斯的踪迹。克劳斯就此失踪。</p><h2 id="第二章-盗贼与公主-奥索赫城堡" tabindex="-1">第二章 盗贼与公主，奥索赫城堡 <a class="header-anchor" href="#第二章-盗贼与公主-奥索赫城堡" aria-label="Permalink to &quot;第二章 盗贼与公主，奥索赫城堡&quot;">​</a></h2><p>新手盗贼达斯特，受父亲韦斯委托，潜入废弃奥索赫城堡，取回<strong>光之卵（Egg of Light）</strong>。光之卵封存着所有岛民对旧世界的痛苦记忆。 在城堡内，达斯特遇见公主库玛托拉。二人遭遇陷阱，城堡进水，两人失散，光之卵也下落不明。与此同时，猪面军团的商人法萨德来到村庄，向村民贩卖“快乐盒子”，引入货币、电视，一点点腐蚀淳朴的村落，猴子萨尔萨被他虐待奴役。</p><h2 id="第三章-猴子萨尔萨的逃亡" tabindex="-1">第三章 猴子萨尔萨的逃亡 <a class="header-anchor" href="#第三章-猴子萨尔萨的逃亡" aria-label="Permalink to &quot;第三章 猴子萨尔萨的逃亡&quot;">​</a></h2><p>操控猴子萨尔萨，被迫为法萨德干活。萨尔萨一路受尽折磨，之后在库玛托拉帮助下逃脱。萨尔萨、库玛托拉、韦斯会合，寻找失踪的达斯特，同时躲避猪面军团追捕。卢卡斯与父亲在森林中保护村庄，抵抗猪面怪物。</p><h2 id="第四章-三年之后-卢卡斯踏上旅途" tabindex="-1">第四章 三年之后，卢卡斯踏上旅途 <a class="header-anchor" href="#第四章-三年之后-卢卡斯踏上旅途" aria-label="Permalink to &quot;第四章 三年之后，卢卡斯踏上旅途&quot;">​</a></h2><p>时间流逝三年。塔兹米利村已经被猪面军团彻底改造，充满工业设施、广告与人造娱乐。卢卡斯成长为少年，与爱犬邦尼一同冒险。 猪面军团在岛上四处抓捕生物改造成合成兽，同时开始寻找七根封印巨龙的魔法针。面具人（Masked Man）作为猪面军团最强战士，抢先拔针。卢卡斯得知：拔出全部七根针，地底巨龙就会苏醒。卢卡斯必须赶在面具人前拔出针，守护岛屿。</p><h2 id="第五章-伙伴重聚-争夺魔法针" tabindex="-1">第五章 伙伴重聚，争夺魔法针 <a class="header-anchor" href="#第五章-伙伴重聚-争夺魔法针" aria-label="Permalink to &quot;第五章 伙伴重聚，争夺魔法针&quot;">​</a></h2><p>卢卡斯一路探索岛屿各地，先后重逢库玛托拉、找回失忆的达斯特。四人小队（卢卡斯、邦尼、达斯特、库玛托拉）集结。 岛上有七位玛吉普西（Magypsy），是七根针的守护者。主角一行人、面具人两边竞速拔针。卢卡斯这边成功拔出三根；面具人夺走另外三根，只剩下第七根、最终之针，藏在新波奇城地下。 途中众人了解岛屿的真相：塔兹米利全村人，都是旧世界大灾变最后的幸存者，他们来到这座与世隔绝的岛屿，把过去痛苦记忆封存进光之卵，重新建立简单和平的生活。</p><h2 id="第六章-新波奇城-波奇的真相" tabindex="-1">第六章 新波奇城，波奇的真相 <a class="header-anchor" href="#第六章-新波奇城-波奇的真相" aria-label="Permalink to &quot;第六章 新波奇城，波奇的真相&quot;">​</a></h2><p>猪面军团建造的巨大都市<strong>新波奇城</strong>，是波奇的帝国。主角一行人闯入波奇帝国大楼顶层，见到波奇·明奇。 波奇是MOTHER2里逃走的那个波奇，利用时间机器不断跳跃到各个时代，见识世间一切，最后只剩下无尽的无聊。他厌倦一切，跑到无处群岛，想要唤醒巨龙、毁灭这个世界取乐。 波奇不会亲自参战，躲进安德纳茨博士制造的<strong>绝对安全舱</strong>。这个舱一旦关上就永远无法打开，波奇将被永久囚禁在舱内，与世隔绝，永生承受孤独。</p><h2 id="第七章-最终针-兄弟对决" tabindex="-1">第七章 最终针，兄弟对决 <a class="header-anchor" href="#第七章-最终针-兄弟对决" aria-label="Permalink to &quot;第七章 最终针，兄弟对决&quot;">​</a></h2><p>主角前往地下第七根针所在地，在此遭遇面具人。面具人摘下面具，真相揭晓：<strong>面具人就是失踪多年的双胞胎哥哥克劳斯</strong>。 克劳斯当年复仇失败，被猪面军团捕获，大脑遭到洗脑改造，失去记忆，成为波奇的武器。兄弟二人被迫战斗。战斗之中，母亲日奈瓦的灵魂之声响起，唤醒克劳斯被封印的记忆。 克劳斯恢复理智，想起自己犯下的所有恶行，内心崩溃。他用雷电攻击卢卡斯身上的富兰克林徽章，雷电反弹，克劳斯身亡。 卢卡斯拔出第七根针，沉睡在地底的巨龙彻底苏醒，大地剧烈震动，无处群岛开始崩塌。</p><h2 id="终章-黑暗尾声" tabindex="-1">终章 黑暗尾声 <a class="header-anchor" href="#终章-黑暗尾声" aria-label="Permalink to &quot;终章 黑暗尾声&quot;">​</a></h2><p>画面陷入一片漆黑。幸存的所有角色依次发声，互相道别。所有人都活了下来。巨龙没有毁灭一切，而是依照卢卡斯温柔的本心，重塑这片土地。岛屿旧文明崩塌，但生命得以延续。 游戏结尾，MOTHER3的金属质感标题，变回质朴自然的样子。</p><h2 id="角色归宿" tabindex="-1">角色归宿 <a class="header-anchor" href="#角色归宿" aria-label="Permalink to &quot;角色归宿&quot;">​</a></h2><ul><li><strong>卢卡斯</strong>：经历丧母、兄弟相残的巨大伤痛，最终做出选择，唤醒巨龙，开启岛屿新生。继续和邦尼相伴。</li><li><strong>邦尼</strong>：始终陪伴卢卡斯，一路并肩战斗。</li><li><strong>达斯特</strong>：找回自我，放下过去，和父亲韦斯重归于好。</li><li><strong>库玛托拉</strong>：完成作为公主的使命，走出奥索赫城堡的宿命。</li><li><strong>弗林特</strong>：失去妻子与长子，目送双胞胎兄弟的悲剧，幸存下来，和村民一起等待新世界。</li><li><strong>波奇</strong>：被锁进绝对安全舱，永远困在其中，不死但永远无法离开，被永恒孤独惩罚。</li><li><strong>克劳斯</strong>：洗脑解除、恢复意识后，选择结束自己。</li></ul><h2 id="mother3游玩时长参考" tabindex="-1">MOTHER3游玩时长参考 <a class="header-anchor" href="#mother3游玩时长参考" aria-label="Permalink to &quot;MOTHER3游玩时长参考&quot;">​</a></h2><ul><li>主线+少量支线，跟着攻略：<strong>20～25小时</strong></li><li>无攻略开荒，正常探索：<strong>28～35小时</strong></li><li>全收集全部隐藏内容：<strong>35～40小时</strong></li></ul><p>这个系列三部的剧情都整理完毕，适合做成可预览网页，工作任务模式处理页面和交互会更完整，要不要用它继续？</p>',24)])])}const p=r(n,[["render",i]]);export{u as __pageData,p as default};
